1	import { render, screen, within } from "@testing-library/react";
2	import { DiaryGrid } from "../diary-grid";
3	import { buildMonth } from "@/lib/diary/month";
4	import { thumbnailPieces } from "@/lib/diary/thumbnail";
5	
6	const pieces = thumbnailPieces([
7	  { category: "Tops", imageUrl: "top.webp" },
8	  { category: "Bottoms", imageUrl: "btm.webp" },
9	  { category: "Shoes", imageUrl: "shoe.webp" },
10	]);
11	
12	const cells = buildMonth(2026, 7, "2026-07-24", [
13	  { worn_on: "2026-07-09", outfitId: "o1", pieces },
14	]);
15	
16	function renderGrid(over: Partial<React.ComponentProps<typeof DiaryGrid>> = {}) {
17	  return render(
18	    <DiaryGrid
19	      cells={cells}
20	      monthLabel="July 2026"
21	      streak={3}
22	      prevHref="/calendar?m=2026-06"
23	      nextHref="/calendar?m=2026-08"
24	      {...over}
25	    />,
26	  );
27	}
28	
29	test("renders a Monday-first weekday header", () => {
30	  renderGrid();
31	  const header = screen.getByTestId("weekday-header");
32	  expect(within(header).getAllByText(/^Mon$/i)[0]).toBeInTheDocument();
33	  expect(within(header).getByText(/^Sun$/i)).toBeInTheDocument();
34	});
35	
36	test("a logged day links to its outfit; an empty day does not", () => {
37	  renderGrid();
38	  expect(screen.getByRole("link", { name: /9 July/i })).toHaveAttribute("href", "/outfits/o1");
39	  expect(screen.queryByRole("link", { name: /10 July/i })).not.toBeInTheDocument();
40	});
41	
42	// getByText("3") would also match the day-3 cell — scope to the pill.
43	test("the streak is shown with its unit", () => {
44	  renderGrid();
45	  const pill = screen.getByTestId("streak-pill");
46	  expect(within(pill).getByText("3")).toBeInTheDocument();
47	  expect(within(pill).getByText(/days/i)).toBeInTheDocument();
48	});
49	
50	// The design's template hard-codes "days"; a first-day streak read "1 days".
51	test("a one-day streak is singular", () => {
52	  renderGrid({ streak: 1 });
53	  const pill = screen.getByTestId("streak-pill");
54	  expect(within(pill).getByText("day")).toBeInTheDocument();
55	  expect(within(pill).queryByText("days")).not.toBeInTheDocument();
56	});
57	
58	test("a zero streak is not rendered as a boast", () => {
59	  renderGrid({ streak: 0 });
60	  expect(screen.queryByTestId("streak-pill")).not.toBeInTheDocument();
61	});
62	
63	test("a logged day renders its look as stacked cutouts", () => {
64	  renderGrid();
65	  const cell = screen.getByRole("link", { name: /9 July/i });
66	  expect(within(cell).getAllByRole("presentation")).toHaveLength(3);
67	});
68	
69	// wear_logs.outfit_id is ON DELETE SET NULL, so a wear outlives its outfit.
70	// The day is still part of the record and the streak — it just goes nowhere.
71	test("a wear whose outfit is gone marks the day but is not a link", () => {
72	  const orphaned = buildMonth(2026, 7, "2026-07-24", [
73	    { worn_on: "2026-07-09", outfitId: null, pieces },
74	  ]);
75	  renderGrid({ cells: orphaned });
76	  expect(screen.queryByRole("link", { name: /9 July/i })).not.toBeInTheDocument();
77	  expect(screen.getByTestId("cell-2026-07-09")).toBeInTheDocument();
78	});
79	
80	test("month navigation points at the neighbouring months", () => {
81	  renderGrid();
82	  expect(screen.getByRole("link", { name: /previous month/i })).toHaveAttribute(
83	    "href",
84	    "/calendar?m=2026-06",
85	  );
86	  expect(screen.getByRole("link", { name: /next month/i })).toHaveAttribute(
87	    "href",
88	    "/calendar?m=2026-08",
89	  );
90	});
91	
92	test("the month label and title head the screen", () => {
93	  renderGrid();
94	  expect(screen.getByText("July 2026")).toBeInTheDocument();
95	  expect(screen.getByRole("heading", { name: /fit diary/i })).toBeInTheDocument();
96	});
97	
98	// A month with nothing logged must explain itself rather than show a bare grid.
99	test("an empty month explains where entries come from", () => {
100	  renderGrid({ cells: buildMonth(2026, 7, "2026-07-24", []) });
101	  expect(screen.getByText(/wear a look/i)).toBeInTheDocument();
102	});
103	
104	test("a month with wears does not show the empty-state footnote", () => {
